begin;
do $test$
declare a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); v text; r jsonb; app uuid; staff_uid uuid; blocked boolean; body jsonb;
begin
 select version into v from community_private.agreement_releases where current;
 insert into auth.users(id) values(a),(b);
 insert into auth.identities(id,user_id,provider_id,provider,identity_data) values(gen_random_uuid(),a,'recruitment-test-a','discord','{}'),(gen_random_uuid(),b,'recruitment-test-b','discord','{}');
 insert into community_private.member_agreements(user_id,age_group,version) values(a,'adult',v),(b,'adult',v);
 body:='{"round":1,"consent":true,"notice_version":"recruitment-2026-11-01","answers":{"username":"Test applicant","age":"18","timezone":"UTC","availability":"Evenings","motivation":"Help the community","rules":"Follow rules","skills":"Patience","experience":"No prior experience","english":"B2","coding":{"Python":0},"markup":{}}}';
 body:=jsonb_set(body,'{round}',to_jsonb((select round from community_private.recruitment_settings)));
 perform set_config('request.jwt.claim.sub','',true);
 blocked:=false;begin perform public.recruitment('responses');exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'FAIL anonymous responses';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 blocked:=false;begin perform public.recruitment('responses');exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'FAIL member responses';end if;
 blocked:=false;begin perform public.recruitment('settings','{}');exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'FAIL member settings';end if;
 blocked:=false;begin perform public.recruitment('submit',body);exception when others then blocked:=true;end;if not blocked then raise exception 'FAIL closed submission';end if;
 update community_private.recruitment_settings set accepting=true;
 blocked:=false;begin perform public.recruitment('submit',jsonb_set(body,'{answers,age}','"15"'));exception when others then blocked:=true;end;if not blocked then raise exception 'FAIL underage';end if;
 blocked:=false;begin perform public.recruitment('submit',jsonb_set(body,'{answers,age}','"17"'));exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'FAIL minor approval';end if;
 blocked:=false;begin perform public.recruitment('submit',jsonb_set(body,'{answers,motivation}','""'));exception when others then blocked:=true;end;if not blocked then raise exception 'FAIL missing required';end if;
 blocked:=false;begin perform public.recruitment('submit',jsonb_set(body,'{answers,coding}','{"Python":8}'));exception when others then blocked:=true;end;if not blocked then raise exception 'FAIL grid';end if;
 r:=public.recruitment('submit',body);app:=(r->>'id')::uuid;
 if (r->>'expires_at')::timestamptz-(r->>'submitted_at')::timestamptz<>interval '90 days' then raise exception 'FAIL retention';end if;
 blocked:=false;begin perform public.recruitment('submit',body);exception when others then blocked:=true;end;if not blocked then raise exception 'FAIL duplicate';end if;
 perform set_config('request.jwt.claim.sub',b::text,true);
 perform public.recruitment('withdraw',jsonb_build_object('id',app));
 if not exists(select 1 from community_private.staff_applications where id=app) then raise exception 'FAIL other member deletion';end if;
 if public.recruitment('status')->'own'<>'null'::jsonb then raise exception 'FAIL receipt leak';end if;
 select user_id into staff_uid from auth.identities where provider='discord' and provider_id='1372803707426701365';
 if staff_uid is null then raise exception 'No staff account for test';end if;
 perform set_config('request.jwt.claim.sub',staff_uid::text,true);
 r:=public.recruitment('responses');
 if not exists(select 1 from jsonb_array_elements(r) x where x->>'id'=app::text) then raise exception 'FAIL staff read';end if;
 r:=public.recruitment('status');
 perform public.recruitment('settings',jsonb_build_object('revision',r->'revision','accepting',false,'closed_message','Test closed'));
 perform set_config('request.jwt.claim.sub',b::text,true);
 blocked:=false;begin perform public.recruitment('submit',body);exception when others then blocked:=true;end;if not blocked then raise exception 'FAIL stale open form';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.recruitment('withdraw',jsonb_build_object('id',app));
 if exists(select 1 from community_private.staff_applications where id=app) then raise exception 'FAIL owner deletion';end if;
end $test$;
set local role anon;
select public.recruitment('status') as anonymous_status;
reset role;
select 'PASS: staff authorization, private receipts, required answers, age, guardian gate, grid validation, duplicate prevention, 90-day expiry, closed/stale submissions and ownership' as result;
rollback;